import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"59、【渙】 坎下巽上","description":"橫渠易說 - 59、【渙】 坎下巽上","frontmatter":{"title":"59、【渙】 坎下巽上","description":"橫渠易說 - 59、【渙】 坎下巽上"},"headers":[],"relativePath":"classics/hengqu/061.md","filePath":"classics/hengqu/061.md"}'),l={name:"classics/hengqu/061.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_59、【渙】-坎下巽上" tabindex="-1">59、【渙】 坎下巽上 <a class="header-anchor" href="#_59、【渙】-坎下巽上" aria-label="Permalink to “59、【渙】 坎下巽上”">​</a></h1><p>萃“王假有廟”，渙然後聚道乃久，故“王假有廟”互見於此。凡言“有廟”者，聚道之極也。</p><h3 id="彖曰-渙亨-剛來而不窮-柔得位乎外而上同。-王假有廟-王乃在中也-利涉大川-乘木有功也。" tabindex="-1">彖曰：渙亨，剛來而不窮，柔得位乎外而上同。“王假有廟”，王乃在中也；“利涉大川”，乘木有功也。 <a class="header-anchor" href="#彖曰-渙亨-剛來而不窮-柔得位乎外而上同。-王假有廟-王乃在中也-利涉大川-乘木有功也。" aria-label="Permalink to “彖曰：渙亨，剛來而不窮，柔得位乎外而上同。“王假有廟”，王乃在中也；“利涉大川”，乘木有功也。”">​</a></h3><h3 id="象曰-風行水上-渙-先王以享於帝立廟。" tabindex="-1">象曰：風行水上，渙，先王以享於帝立廟。 <a class="header-anchor" href="#象曰-風行水上-渙-先王以享於帝立廟。" aria-label="Permalink to “象曰：風行水上，渙，先王以享於帝立廟。”">​</a></h3><p>財散則民聚，王乃在渙中之一也。</p><h3 id="初六-用拯馬壯-吉。-象曰-初六之吉-順也。" tabindex="-1">初六，用拯馬壯，吉。 象曰：初六之吉，順也。 <a class="header-anchor" href="#初六-用拯馬壯-吉。-象曰-初六之吉-順也。" aria-label="Permalink to “初六，用拯馬壯，吉。 象曰：初六之吉，順也。”">​</a></h3><p>處險之下，故必用拯，無應於上，順比九二之剛，拯而馬壯，其吉宜也。</p><h3 id="九二-渙奔其杌-悔亡。-象曰-渙奔其杌-得願也。" tabindex="-1">九二，渙奔其杌，悔亡。 象曰：“渙奔其杌”，得願也。 <a class="header-anchor" href="#九二-渙奔其杌-悔亡。-象曰-渙奔其杌-得願也。" aria-label="Permalink to “九二，渙奔其杌，悔亡。 象曰：“渙奔其杌”，得願也。”">​</a></h3><p>奮於險中，進而之前，則難解悔亡，故曰“奔其杌”，三四皆險，故曰“得願”，若退累於初，則險不能出，其悔終存。</p><h3 id="六三-渙其躬-無悔。-象曰-渙其躬-志在外也。" tabindex="-1">六三，渙其躬，無悔。 象曰：“渙其躬”，志在外也。 <a class="header-anchor" href="#六三-渙其躬-無悔。-象曰-渙其躬-志在外也。" aria-label="Permalink to “六三，渙其躬，無悔。 象曰：“渙其躬”，志在外也。”">​</a></h3><p>援上而進，惟求自脫於險，無悔而已，非能及物者也。</p><h3 id="六四-渙其群-元吉。渙有丘-匪夷所思。-象曰-渙其群元吉-光大也。" tabindex="-1">六四，渙其群，元吉。渙有丘，匪夷所思。 象曰：“渙其群元吉”，光大也。 <a class="header-anchor" href="#六四-渙其群-元吉。渙有丘-匪夷所思。-象曰-渙其群元吉-光大也。" aria-label="Permalink to “六四，渙其群，元吉。渙有丘，匪夷所思。 象曰：“渙其群元吉”，光大也。”">​</a></h3><p>己處險外，無私其應，常以拯眾為心，則其志光大獲吉；若志在所歸之地，近累於五，則非能平均其慮者也。</p><h3 id="九五-渙汗其大號-渙王居-無咎。-象曰-王居無咎-正位也。" tabindex="-1">九五，渙汗其大號，渙王居，無咎。 象曰：“王居無咎”，正位也。 <a class="header-anchor" href="#九五-渙汗其大號-渙王居-無咎。-象曰-王居無咎-正位也。" aria-label="Permalink to “九五，渙汗其大號，渙王居，無咎。 象曰：“王居無咎”，正位也。”">​</a></h3><p>為渙之主，使物偏被其澤，正位凝命，可以免咎，不私於應，故能均布其大號也。渙然廓大，以王道自居乃無咎。</p><h3 id="上九-渙其血-去逖出-無咎。-象曰-渙其血-遠害也。" tabindex="-1">上九，渙其血，去逖出，無咎。 象曰：“渙其血”，遠害也。 <a class="header-anchor" href="#上九-渙其血-去逖出-無咎。-象曰-渙其血-遠害也。" aria-label="Permalink to “上九，渙其血，去逖出，無咎。 象曰：“渙其血”，遠害也。”">​</a></h3><p>乘剛在上，若繫於三，害不可免，能絕棄陰類，遠去其難，則可免咎。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
